#include "Includes/obfuscate.h"
#include "Menu/FeatureList.hpp"
#include "Menu/Menu.hpp"
#include "boku/feature_registry.h"
#include "boku/jni_util.h"
#include "boku/player_service.h"

namespace {

// The queue copies the text itself, so the Java string borrow only lives for
// the duration of this call.
jboolean enqueueKick(JNIEnv *env, jstring key, jstring name, bool permanent) {
    StringUtf keyText(env, key);
    if (!keyText)
        return JNI_FALSE;

    StringUtf nameText(env, name);
    const char *playerName = nameText ? nameText.get() : nullptr;
    bool accepted = player::enqueueKick(keyText.get(), playerName, permanent);
    return accepted ? JNI_TRUE : JNI_FALSE;
}

jboolean enqueueKickHost(JNIEnv *env, jstring name) {
    StringUtf nameText(env, name);
    const char *hostName = nameText ? nameText.get() : nullptr;
    return player::enqueueKickHost(hostName) ? JNI_TRUE : JNI_FALSE;
}

jboolean enqueueCopy(JNIEnv *env, jstring key, jstring name) {
    StringUtf keyText(env, key);
    if (!keyText)
        return JNI_FALSE;

    StringUtf nameText(env, name);
    const char *playerName = nameText ? nameText.get() : nullptr;
    return player::enqueueCopy(keyText.get(), playerName) ? JNI_TRUE : JNI_FALSE;
}

jboolean enqueueCopyAvatar(JNIEnv *env, jstring key) {
    StringUtf keyText(env, key);
    if (!keyText)
        return JNI_FALSE;
    return player::enqueueCopyAvatar(keyText.get()) ? JNI_TRUE : JNI_FALSE;
}

} // namespace

void Init(JNIEnv *env, jobject thiz, jobject ctx, jobject title, jobject subtitle) {
    (void)thiz;
    (void)ctx;
    setText(env, title, OBFUSCATE("BOKU Menu 1.1"));
    setText(env, subtitle, OBFUSCATE("Pertama kali buat mod menu, I hope this goes well"));
}

jstring Icon(JNIEnv *env, jobject thiz) {
    (void)thiz;
    // Stock menu icon, used until the user picks their own image source. The
    // 512x512 PNG below is converted to base64 as is.
    return env->NewStringUTF(OBFUSCATE(""));
}

